<script setup lang="ts">
import {computed} from 'vue';
import type {ExecutionPlan} from '../executionTypes';
import type {SharedStep} from '../systemScenario';
const props=defineProps<{step:SharedStep;plan:ExecutionPlan;previous:SharedStep[]}>();
const channel=computed(()=>props.plan.channels?.find(c=>c.id===props.step.message?.channelId));
const aliases=computed(()=>[...new Set(props.previous.filter(s=>s.kind==='dispatch'&&s.message?.channelId===props.step.message?.channelId).map(s=>s.message!.alias).filter(Boolean))]);
function changeChannel(id:string){props.step.message={channelId:id,...(props.step.kind==='dispatch'?{routeId:props.plan.channels?.find(c=>c.id===id)?.model.model.routes[0]?.id,sourceCommandId:'',alias:'',expectedRevision:0}:props.step.kind==='broker_restart'?{}:{alias:'',fault:''})};props.step.expectedMessageStatus='';}
const outcomes=['dispatched','dispatch_replayed','dispatch_conflict','missing_intent','missing_source_message','missing_message','acknowledged','acknowledgement_lost','recipient_unacknowledged','dropped','already_acknowledged','broker_restarted'];
</script>
<template><section v-if="step.message"><label>Message channel *<select :value="step.message.channelId" @change="changeChannel(($event.target as HTMLSelectElement).value)"><option v-for="c in plan.channels||[]" :key="c.id" :value="c.id">{{c.model.model.name}} · {{c.provider.id}}</option></select></label>
 <template v-if="step.kind==='dispatch'"><label>Route *<select v-model="step.message.routeId"><option value="">Choose a route…</option><option v-for="r in channel?.model.model.routes||[]" :key="r.id" :value="r.id">{{r.name}} · {{r.sourceInstanceId}} → {{r.targetInstanceId}}</option></select></label><label>Source command ID (or choose an upstream message below)<input v-model="step.message.sourceCommandId" @input="step.message.sourceMessage=''"/></label><label>Upstream delivered message<select v-model="step.message.sourceMessage" @change="step.message.sourceCommandId=''"><option value="">Use source command ID</option><option v-for="alias in aliases" :key="alias" :value="alias">{{alias}}</option></select></label><label>New message alias *<input v-model="step.message.alias"/></label><label>Recipient expected revision *<input type="number" min="0" step="1" v-model.number="step.message.expectedRevision"/></label><p>Dispatch freezes the recipient command, mapped payload and expected revision. Retrying dispatch must retain them.</p></template>
 <template v-else-if="step.kind!=='broker_restart'"><label>Earlier message alias *<select v-model="step.message.alias"><option value="">Choose a dispatched message…</option><option v-for="alias in aliases" :key="alias" :value="alias">{{alias}}</option></select></label><label>Delivery fault<select v-model="step.message.fault"><option value="">None</option><option value="drop_before_receive">Drop before recipient</option><option value="before_recipient_commit">Rollback before recipient commit</option><option value="after_recipient_commit_before_ack">Commit, then lose acknowledgement</option></select></label><p>Retry submits the same frozen command identity. Recipient receipts prevent a second business write.</p></template>
 <p v-else>Restart the modeled durable broker. Pending envelopes, attempts and acknowledgements survive. This does not restart state owners.</p>
 <label>Expected transport outcome (optional)<select v-model="step.expectedMessageStatus"><option value="">No assertion</option><option v-for="s in outcomes" :key="s">{{s}}</option></select></label>
</section></template>
<style scoped>section{min-width:0}label{display:grid;gap:6px;margin:10px 0}input,select{min-width:0;width:100%;box-sizing:border-box;padding:8px}p{font-size:12px;line-height:1.5}</style>
